package com.example.carteirainvestimento.service;
import java.time.OffsetDateTime; import java.time.ZoneOffset;
import com.example.carteirainvestimento.domain.Carteira; import com.example.carteirainvestimento.dto.carteira.CarteiraRequest; import com.example.carteirainvestimento.exception.BusinessRuleException; import com.example.carteirainvestimento.exception.ResourceNotFoundException; import com.example.carteirainvestimento.repository.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CarteiraService { private final CarteiraRepository carteiras; private final AtivoCarteiraRepository ativos; public CarteiraService(CarteiraRepository c, AtivoCarteiraRepository a){carteiras=c;ativos=a;}
@Transactional public Carteira criar(CarteiraRequest r){Carteira c=new Carteira();c.setNome(r.nome());c.setDescricao(r.descricao());c.setDataCriacao(OffsetDateTime.now(ZoneOffset.UTC));return carteiras.save(c);} @Transactional(readOnly=true) public Page<Carteira> listar(Pageable p){return carteiras.findAll(p);} @Transactional(readOnly=true) public Carteira buscar(Long id){return carteiras.findById(id).orElseThrow(()->new ResourceNotFoundException("Carteira nao encontrada"));} @Transactional public Carteira atualizar(Long id,CarteiraRequest r){Carteira c=buscar(id);c.setNome(r.nome());c.setDescricao(r.descricao());return carteiras.save(c);} @Transactional public void excluir(Long id){if(ativos.existsByCarteiraId(id))throw new BusinessRuleException("Carteira possui posicoes");carteiras.delete(buscar(id));}}
